<?php declare(strict_types=1);require_once __DIR__.'/../../../bootstrap/app.php';use App\Services\Auth;use App\Services\DispatchService;use App\Security\Csrf;Auth::requirePermission('TRIP_VIEW_DRIVER');$id=(int)($_GET['id']??0);$r=DispatchService::find($id);if(!$r){http_response_code(404);exit('Trip not found.');}$mine=array_filter(DispatchService::driverTrips((int)Auth::user()['id']),fn($x)=>(int)$x['trip_id']===$id);if(!$mine){http_response_code(403);exit('Forbidden');}$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid token.');DispatchService::transition($id,$_POST['to']??'',(int)Auth::user()['id']);header('Location: ?id='.$id);exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}$r=DispatchService::find($id);}$next=['planned'=>'driver_ready','dispatched'=>'in_transit','in_transit'=>'arrived','arrived'=>'delivered'][$r['current_status']]??null;$pageTitle='Driver Trip';require BASE_PATH.'/app/Views/layout/header.php';?><h1><?=h($r['trip_ref'])?></h1><div class="card"><p><?=h($r['origin_city'].' → '.$r['destination_city'])?></p><p>Status: <?=h($r['current_status'])?></p><p><a href="<?=h(\App\Support\Url::to('tracking/view.php?id='.$id))?>">Open tracking & report an exception</a></p></div><?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;if($next):?><form method="post"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="to" value="<?=h($next)?>"><button class="button">Mark <?=h(str_replace('_',' ',$next))?></button></form><?php endif;?><?php require BASE_PATH.'/app/Views/layout/footer.php';
